class Solution {
public:
    int maxSubArray(vector<int>& nums) {
        long long maxEnding = nums[0];
        long long maxSoFar = nums[0];
        for (int i = 1; i < (int)nums.size(); ++i) {
            maxEnding = max<long long>(nums[i], maxEnding + nums[i]);
            maxSoFar = max(maxSoFar, maxEnding);
        }
        return (int)maxSoFar;
    }
};
